{"content":"import { create } from 'zustand';
import type { Vec3Tuple } from '../types';

// ---------------------------------------------------------------------------
// Aim store — Phase 6 (T17)
//
// Tracks the player's aim direction, shot power, charging state, and camera
// mode.  Updated every frame by the useAim hook (mouse movement) and the
// usePower hook (charging animation).
// ---------------------------------------------------------------------------

interface AimStoreState {
  /** Normalised aim direction on the XZ plane */
  direction: Vec3Tuple;
  /** Shot power clamped to [0, 1] */
  power: number;
  /** True while the player is holding the mouse button to charge power */
  isCharging: boolean;
  /** Camera mode toggle */
  cameraMode: 'orbit' | 'topdown';
}

interface AimStoreActions {
  setDirection: (dir: Vec3Tuple) => void;
  setPower: (power: number) => void;
  /** Alias: set isCharging to true */
  setIsCharging: (charging: boolean) => void;
  /** Begin charging from 0 */
  startCharging: () => void;
  /** Stop charging (power stays at current value) */
  stopCharging: () => void;
  /** Reset power and charging for next shot */
  resetPower: () => void;
  toggleCameraMode: () => void;
  setCameraMode: (mode: 'orbit' | 'topdown') => void;
}

export const useAimStore = create<AimStoreState & AimStoreActions>((set) => ({
  direction: [0, 0, 1],
  power: 0,
  isCharging: false,
  cameraMode: 'orbit',

  setDirection: (dir: Vec3Tuple) => set({ direction: dir }),
  setPower: (power: number) => set({ power: Math.min(1, Math.max(0, power)) }),
  setIsCharging: (charging: boolean) => set({ isCharging: charging }),
  startCharging: () => set({ isCharging: true, power: 0 }),
  stopCharging: () => set({ isCharging: false }),
  resetPower: () => set({ power: 0, isCharging: false }),
  toggleCameraMode: () =>
    set((s) => ({ cameraMode: s.cameraMode === 'orbit' ? 'topdown' : 'orbit' })),
  setCameraMode: (mode) => set({ cameraMode: mode }),
}));","end_line":52,"start_line":0,"total_lines":53}

{"content":"import { Canvas } from '@react-three/fiber';
import * as THREE from 'three';
import { OrbitControls } from '@react-three/drei';
import Table from './Table';
import Balls from './Balls';
import CueStick from './CueStick';
import AimLine from './AimLine';
import PhysicsWorld from '../physics/PhysicsWorld';
import useSettleDetector from '../hooks/useSettleDetector';
import useShotSequence from '../hooks/useShotSequence';
import {
  CAMERA_DEFAULT_POSITION,
  CAMERA_FOV,
  HALF_LENGTH,
  HALF_WIDTH,
  FLOOR_Y,
} from '../constants/table';

/**
 * Wrapper for game hooks that must run inside the Canvas/Physics context.
 */
function GameHooks() {
  useSettleDetector();
  useShotSequence();
  return null;
}

/**
 * R3F Canvas with PCFSoftShadowMap (2048×2048), perspective camera (45 deg FOV)
 * positioned above the table at an angle, ambient + directional + point lights,
 * and OrbitControls constrained so the user cannot go below the table.
 *
 * Phase 8 (T25): shadow map upgraded to PCFSoftShadowMap for soft shadow edges,
 * directional light shadow camera covers the full table area, balls cast shadows
 * onto the felt surface.
 */
export default function Scene() {
  const orbitTarget: [number, number, number] = [0, 0, 0];

  return (
    <Canvas
      shadows
      gl={{
        shadowMap: {
          enabled: true,
          type: THREE.PCFSoftShadowMap,
        } as any,
      }}
      camera={{
        position: CAMERA_DEFAULT_POSITION,
        fov: CAMERA_FOV,
        near: 0.01,
        far: 50,
      }}
      style={{ width: '100%', height: '100%' }}
    >
      <color attach="background" args={['#1a1a2e']} />

      {/* Lighting */}
      <ambientLight intensity={0.35} color="#ffffff" />
      <directionalLight
        position={[0, 3, 0.5]}
        intensity={1.2}
        color="#fffbe6"
        castShadow
        shadow-mapSize-width={2048}
        shadow-mapSize-height={2048}
        shadow-camera-near={0.5}
        shadow-camera-far={8}
        shadow-camera-left={-HALF_WIDTH - 0.3}
        shadow-camera-right={HALF_WIDTH + 0.3}
        shadow-camera-top={HALF_LENGTH + 0.3}
        shadow-camera-bottom={-HALF_LENGTH - 0.3}
        shadow-bias={-0.0005}
        shadow-normalBias={0.02}
      />
      <pointLight
        position={[-HALF_WIDTH * 0.4, 1.5, -HALF_LENGTH * 0.6]}
        intensity={0.5}
        color="#fff5e6"
        distance={5}
        decay={2}
      />
      <pointLight
        position={[HALF_WIDTH * 0.4, 1.5, HALF_LENGTH * 0.6]}
        intensity={0.5}
        color="#fff5e6"
        distance={5}
        decay={2}
      />

      {/* Physics world wrapping all game objects */}
      <PhysicsWorld>
        <Table />
        <Balls />
        <CueStick />
        <AimLine />
        <GameHooks />
      </PhysicsWorld>

      {/* Camera controls */}
      <OrbitControls
        target={orbitTarget}
        enablePan={false}
        enableDamping
        dampingFactor={0.08}
        minPolarAngle={0.2}
        maxPolarAngle={Math.PI / 2.15}
        minDistance={0.8}
        maxDistance={4.5}
      />

      {/* ── Dark floor plane beneath table (Phase 8, T25) ── */}
      <mesh
        rotation={[-Math.PI / 2, 0, 0]}
        position={[0, FLOOR_Y, 0]}
        receiveShadow
      >
        <planeGeometry args={[20, 20]} />
        <meshStandardMaterial color="#0e0806" roughness={0.95} metalness={0} />
      </mesh>

      <fog attach="fog" args={['#1a1a2e', 6, 14]} />
    </Canvas>
  );
}","end_line":125,"start_line":0,"total_lines":126}

{"content":"import Scene from './components/Scene';
import GameUI from './components/GameUI';

/**
 * Root component for the 3D 8-Ball Pool Game.
 *
 * Architecture:
 *   App
 *   ├── Scene (R3F Canvas)
 *   │   ├── PhysicsWorld
 *   │   ├── Table
 *   │   ├── Balls (16x BallBody + Ball mesh)
 *   │   ├── CueStick
 *   │   └── AimLine
 *   └── GameUI (HTML overlay)
 */
function App() {
  return (
    <div
      style={{
        width: '100vw',
        height: '100vh',
        background: '#1a1a2e',
        overflow: 'hidden',
      }}
    >
      <Scene />
      <GameUI />
    </div>
  );
}

export default App;","end_line":32,"start_line":0,"total_lines":33}

